using AITaskAgent.LLM.Constants;

namespace AITaskAgent.LLM.Models;
/// <summary>
/// A single candidate generated by the LLM.
/// </summary>
public sealed record LlmResponse
{
    /// <summary>The sequence index of this candidate.</summary>
    public int Index { get; init; }

    /// <summary>The generated content for this candidate.</summary>
    public required string Content { get; init; }

    /// <summary>Internal reasoning/thinking.</summary>
    public string? Reasoning { get; init; }

    /// <summary>Normalized reason why the generation finished.</summary>
    public FinishReason? FinishReason { get; init; }

    /// <summary>Provider-specific finish reason string.</summary>
    public string? RawFinishReason { get; init; }

    /// <summary>Tool calls requested by the LLM in this candidate.</summary>
    public List<ToolCall>? ToolCalls { get; init; }
}